// The display face of each pairing, cut down to A to Z and 0 to 9 at weight 400, for the home-screen monogram.
// Generated from the next/font builds of the six pairings. Every family is under the SIL Open Font License 1.1
// (src/lib/pwa/fonts/OFL.txt; THIRD_PARTY_NOTICES.md lists each copyright). Each cut keeps its name table, with its
// copyright line and a link to the license. A subset is a Modified Version, so the Playfair Display cut, whose name
// is reserved, is renamed Monogram Editorial in its name table.
import type { PairingId } from "@/lib/brand/pairings";

export const MONOGRAM_GLYPHS = /^[A-Z0-9]+$/;

export const MONOGRAM_FONTS: Record<PairingId, { name: string; data: string }> = {
  sanctuary: { name: "Fraunces", data: "" },
  modern: { name: "Inter Tight", data: "" },
  editorial: { name: "Monogram Editorial", data: "" },
  grotesk: { name: "Space Grotesk Light", data: "" },
  classic: { name: "Libre Baskerville", data: "" },
  humanist: { name: "Plus Jakarta Sans", data: "" },
};
